    'PR China': 'China', 'People Republic of China': 'China', "People's Republic of China": 'China',
    'United States': 'USA', 'US': 'USA', 'United States of America': 'USA',
    'Republic of Korea': 'South Korea', 'Korea': 'South Korea',
    'UK': 'United Kingdom', 'Great Britain': 'United Kingdom', 'England': 'United Kingdom',
    'Scotland': 'United Kingdom', 'Wales': 'United Kingdom',
    'Russian Federation': 'Russia',
}
df['country_clean'] = df['country'].replace(country_map)

def extract_primary_type(rt):
    if pd.isna(rt):
        return 'Unknown'
    parts = [p.strip() for p in str(rt).split(';')]
    for p in parts:
        if p == 'Preprint': return 'Preprint'
        if p == 'Case Reports': return 'Case Report'
        if p == 'Systematic Review': return 'Systematic Review'
        if p == 'Review': return 'Review'
        if p == 'Journal Article': return 'Journal Article'
    return parts[0]

df['primary_research_type'] = df['research_type'].apply(extract_primary_type)
